import{_ as a,a0 as i,w as p,s,I as l,x as e,a1 as r,A as n,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"寫直白的代碼 | LCTT x X-CMD","titleTemplate":false,"description":"寫直白的代碼 | LCTT (201811) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"寫直白的代碼 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"寫直白的代碼 | LCTT (201811) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201811/20180127 Write Dumb Code","title":"寫直白的代碼","tag":"201811","desc":""},"relativePath":"201811/20180127 Write Dumb Code.md","filePath":"[post].md"}'),m={name:"201811/20180127 Write Dumb Code.md"};function u(f,t,T,b,C,x){const o=i("Link");return p(),s("div",null,[t[16]||(t[16]=l("h1",{id:"寫直白的代碼",tabindex:"-1"},[e("寫直白的代碼 "),l("a",{class:"header-anchor",href:"#寫直白的代碼","aria-label":"Permalink to “寫直白的代碼”"},"​")],-1)),t[17]||(t[17]=l("p",null,"為開源項目作貢獻最好的方式是為它減少代碼，我們應致力於寫出讓新手程序員無需註釋就容易理解的代碼，讓維護者也無需花費太多精力就能着手維護。",-1)),t[18]||(t[18]=l("p",null,"在學生時代，我們會更多地用複雜巧妙的技術去挑戰新的難題。首先我們會學習循環，然後是函數啊，類啊，等等。當我們到達一定高的程度，能用更高級的技術寫更長的程序，我們會因此受到稱讚。此刻我們發現老司機們用 monads 而新手們用 loop 作循環。",-1)),t[19]||(t[19]=l("p",null,"之後我們畢業找了工作，或者和他人合作開源項目。我們用在學校裏學到的各種炫技尋求並驕傲地給出解決方案的代碼實現。",-1)),t[20]||(t[20]=l("p",null,[l("em",null,"哈哈，我能擴展這個項目，並實現某牛 X 功能啦，我這裏能用繼承啦，我太聰明啦！")],-1)),l("p",null,[t[1]||(t[1]=e("我們實現了某個小的功能，並以充分的理由覺得自己做到了。現實項目中的編程卻不是針對某某部分的功能而言。以我個人的經驗而言，以前我很開心的去寫代碼，並驕傲地向世界展示我所知道的事情。有例為證，作為對某種編程技術的偏愛，這是用另一種元編程語言構建的一個 ",-1)),r(o,{href:"https://github.com/mrocklin/matrix-algebra"},{default:n(()=>[...t[0]||(t[0]=[e("線性代數語言",-1)])]),_:1}),t[2]||(t[2]=e("，注意，這麼多年以來一直沒人願意碰它。",-1))]),t[21]||(t[21]=d('<p>在維護了更多的代碼後，我的觀點發生了變化。</p><ol><li>我們不應去刻意探求如何構建軟件。軟件是我們為解決問題所付出的代價，那才是我們真實的目的。我們應努力為了解決問題而構建較小的軟件。</li><li>我們應使用盡可能簡單的技術，那麼更多的人就越可能會使用，並且無需理解我們所知的高級技術就能擴展軟件的功能。當然，在我們不知道如何使用簡單技術去實現時，我們也可以使用高級技術。</li></ol><p>所有的這些例子都不是聽來的故事。我遇到的大部分人會認同某些部分，但不知為什麼，當我們向一個新項目貢獻代碼時又會忘掉這個初衷。直覺裏用複雜技術去構建的念頭往往會佔據上風。</p><h3 id="軟件是種投入" tabindex="-1">軟件是種投入 <a class="header-anchor" href="#軟件是種投入" aria-label="Permalink to “軟件是種投入”">​</a></h3><p>你寫的每行代碼都要花費人力。寫代碼當然是需要時間的，也許你會認為只是你個人在奉獻，然而這些代碼在被審閲的時候也需要花時間理解，對於未來維護和開發人員來説，他們在維護和修改代碼時同樣要花費時間。否則他們完全可以用這時間出去曬曬太陽，或者陪伴家人。</p><p>所以，當你向某個項目貢獻代碼時，請心懷謙恭。就像是，你正和你的家人進餐時，餐桌上卻沒有足夠的食物，你只索取你所需的部分，別人對你的自我約束將肅然起敬。以更少的代碼去解決問題是很難的，你肩負重任的同時自然減輕了別人的重負。</p><h3 id="技術越複雜越難維護" tabindex="-1">技術越複雜越難維護 <a class="header-anchor" href="#技術越複雜越難維護" aria-label="Permalink to “技術越複雜越難維護”">​</a></h3><p>作為學生，逐漸使用高端技術證明了自己的價值。這體現在，首先我們有能力在開源項目中使用函數，接着是類，然後是高階函數，monads 等等。我們向同行顯示自己的解決方案時，常因自己所用技術高低而感到自豪或卑微。</p><p>而在現實中，和團隊去解決問題時，情況發生了逆轉。現在，我們致力於儘可能使用簡單的代碼去解決問題。簡單方式解決問題使新手程序員能夠以此擴展並解決其他問題。簡單的代碼讓別人容易上手，效果立竿見影。我們藉以只用簡單的技術去解決難題，從而展示自己的價值。</p><p><em>看，我用循環替代了遞歸函數並且一樣達到了我們的需求。當然我明白這是不夠聰明的做法，不過我注意到新手同事在這裏會遇上麻煩，我覺得這種改變將有所幫助吧。</em></p><p>如果你是個好的程序員，你不需要證明你知道很多炫技。相應的，你可以通過用一個簡單的方法解決一個問題來顯示你的價值，並激發你的團隊在未來的時間裏去完善它。</p><h3 id="當然-也請保持節制" tabindex="-1">當然，也請保持節制 <a class="header-anchor" href="#當然-也請保持節制" aria-label="Permalink to “當然，也請保持節制”">​</a></h3><p>話雖如此，過於遵循 “用簡單的工具去構建” 的教條也會降低生產力。通常用遞歸會比用循環解決問題更簡單，用類或 monad 才是正確的途徑。還有兩種情況另當別論，一是隻是隻為滿足自我而創建的系統，或者是別人毫無構建經驗的系統。</p><hr>',14)),l("p",null,[t[4]||(t[4]=e("via: ",-1)),r(o,{href:"http://matthewrocklin.com/blog/work/2018/01/27/write-dumb-code"},{default:n(()=>[...t[3]||(t[3]=[e("http://matthewrocklin.com/blog/work/2018/01/27/write-dumb-code",-1)])]),_:1})]),l("p",null,[t[8]||(t[8]=e("作者：",-1)),r(o,{href:"http://matthewrocklin.com"},{default:n(()=>[...t[5]||(t[5]=[e("Matthew Rocklin",-1)])]),_:1}),t[9]||(t[9]=e(" 譯者：",-1)),r(o,{href:"https://github.com/plutoid"},{default:n(()=>[...t[6]||(t[6]=[e("plutoid",-1)])]),_:1}),t[10]||(t[10]=e(" 校對：",-1)),r(o,{href:"https://github.com/wxy"},{default:n(()=>[...t[7]||(t[7]=[e("wxy",-1)])]),_:1})]),l("p",null,[t[13]||(t[13]=e("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[11]||(t[11]=[e("LCTT",-1)])]),_:1}),t[14]||(t[14]=e(" 原創編譯，",-1)),r(o,{href:"https://linux.cn/"},{default:n(()=>[...t[12]||(t[12]=[e("Linux中國",-1)])]),_:1}),t[15]||(t[15]=e(" 榮譽推出",-1))])])}const D=a(m,[["render",u]]);export{w as __pageData,D as default};
